const formatTime = (value: string) => {
  const date = new Date(value);
  return Number.isNaN(date.getTime())
    ? "now"
    : new Intl.DateTimeFormat("en", {
        hour: "numeric",
        minute: "2-digit",
      }).format(date);
};
const formatDateTime = (value: string) => {
  const date = new Date(value);
  return Number.isNaN(date.getTime())
    ? "time unknown"
    : new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" }).format(date);
};
const formatRelativeTime = (value: string, now = Date.now()) => {
  const date = new Date(value);
  const timestamp = date.getTime();
  if (Number.isNaN(timestamp)) return "time unknown";
  const elapsed = Math.max(0, now - timestamp);
  const minute = 60_000;
  const hour = 60 * minute;
  const day = 24 * hour;
  const week = 7 * day;
  if (elapsed < minute) return "just now";
  if (elapsed < hour) {
    const minutes = Math.floor(elapsed / minute);
    return `${minutes}m ago`;
  }
  if (elapsed < day) {
    const hours = Math.floor(elapsed / hour);
    return `${hours}h ago`;
  }
  if (elapsed < week) {
    const days = Math.floor(elapsed / day);
    return `${days} ${days === 1 ? "day" : "days"} ago`;
  }
  const weeks = Math.floor(elapsed / week);
  return `${weeks} ${weeks === 1 ? "week" : "weeks"} ago`;
};
const formatHistoryTimestamp = (value: string) => {
  const date = new Date(value);
  return Number.isNaN(date.getTime())
    ? "now"
    : `${new Intl.DateTimeFormat("en", { hour: "numeric", minute: "2-digit" }).format(date)} · ${new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric" }).format(date)}`;
};
const formatRecentPostTimestamp = (value: string, now = Date.now()) => {
  const timestamp = new Date(value).getTime();
  const elapsed = now - timestamp;
  return Number.isFinite(timestamp) && elapsed >= 0 && elapsed < 24 * 60 * 60_000
    ? formatRelativeTime(value, now)
    : formatHistoryTimestamp(value);
};
const localDateKey = (value: string | number | Date) => {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "unknown";
  return `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
};
const formatActivityDateGroup = (value: string, now = Date.now()) => {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "Date unknown";
  const today = new Date(now);
  const yesterday = new Date(now);
  yesterday.setDate(yesterday.getDate() - 1);
  const key = localDateKey(date);
  if (key === localDateKey(today)) return "Today";
  if (key === localDateKey(yesterday)) return "Yesterday";
  return new Intl.DateTimeFormat("en", {
    weekday: "long",
    month: "long",
    day: "numeric",
    ...(date.getFullYear() === today.getFullYear() ? {} : { year: "numeric" }),
  }).format(date);
};
const formatCountdown = (value: string | undefined, now = Date.now()) => {
  if (!value) return undefined;
  const remaining = new Date(value).getTime() - now;
  if (!Number.isFinite(remaining)) return undefined;
  if (remaining <= 0) return "now";
  const totalSeconds = Math.ceil(remaining / 1_000);
  const hours = Math.floor(totalSeconds / 3_600);
  const minutes = Math.floor((totalSeconds % 3_600) / 60);
  const seconds = totalSeconds % 60;
  return hours > 0
    ? `${hours}:${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`
    : `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
};
function useOperationalHealth(presenceId?: string, refreshKey = 0) {
  const [health, setHealth] = useState<OperationalHealthSnapshot | null>(null);
  const healthEtag = useRef<string | null>(null);
  useEffect(() => {
    if (!presenceId) return;
    let active = true;
    let timerId: ReturnType<typeof setTimeout> | undefined;

    const load = async () => {
      try {
        const headers = new Headers();
        if (healthEtag.current) headers.set("If-None-Match", healthEtag.current);
        const response = await fetch(`/api/runtime/health?presenceId=${encodeURIComponent(presenceId)}`, { headers, cache: "no-store" });
        if (response.status === 304) return;
        if (!response.ok || !active) return;
        const etag = response.headers.get("etag");
        if (etag) healthEtag.current = etag;
        const payload = await response.json() as OperationalHealthSnapshot;
        setHealth(payload);
      } catch { /* Health is advisory; Activity remains usable when the probe is down. */ }
      finally {
        if (active) {
          timerId = setTimeout(() => void load(), 10_000);
        }
      }
    };
    void load();
    return () => {
      active = false;
      if (timerId) clearTimeout(timerId);
    };
  }, [presenceId, refreshKey]);
  return health;
}

function OperationalHealthIndicator({ health, onOpen }: { health: OperationalHealthSnapshot | null; onOpen: () => void }) {
  if (!health) {
    return (
      <button type="button" className="global-health-indicator global-health-unknown" onClick={onOpen} aria-label="Operating health: Connecting">
        <span aria-hidden="true">◌</span> Health connecting...
      </button>
    );
  }
  const copy = health.status === "needs_you"
    ? "Needs You"
    : health.status === "degraded"
      ? "Degraded · capability unavailable"
    : health.status === "recovering"
      ? "Recovering body · no action needed"
      : health.status === "waiting"
        ? "Waiting · resumes automatically"
        : "Healthy";
  const symbol = health.status === "needs_you" || health.status === "degraded" ? "⚠" : health.status === "recovering" ? "◐" : health.status === "waiting" ? "◷" : "●";
  return <button type="button" className={`global-health-indicator global-health-${health.status}`} onClick={onOpen} aria-label={`Operating health: ${copy}`}><span aria-hidden="true">{symbol}</span> {copy}</button>;
}
